package repligraph

import (
	"bytes"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"

	"lukechampine.com/blake3"

	"theorem.dev/repligraph/token"
	"theorem.dev/repligraph/tools"
	"theorem.dev/repligraph/tree"
)

const (
	ManifestName   = "manifest.json"
	TranscriptName = "transcript"
	ArtifactDir    = "artifact"
)

type Hash [32]byte

func (h Hash) String() string { return hex.EncodeToString(h[:]) }

func (h Hash) MarshalText() ([]byte, error) { return []byte(h.String()), nil }

func (h *Hash) UnmarshalText(text []byte) error {
	if len(text) != 64 {
		return errors.New("invalid hash length")
	}
	_, err := hex.Decode(h[:], text)
	return err
}

type Manifest struct {
	Version        int    `json:"version"`
	Profile        string `json:"profile"`
	TranscriptHash Hash   `json:"transcript_hash"`
	ArtifactRoot   Hash   `json:"artifact_root"`
}

func ReadManifest(fsys fs.FS) (Manifest, error) {
	var m Manifest
	blob, err := fs.ReadFile(fsys, ManifestName)
	if err != nil {
		return m, err
	}
	dec := json.NewDecoder(bytes.NewReader(blob))
	dec.DisallowUnknownFields()
	if err := dec.Decode(&m); err != nil {
		return m, fmt.Errorf("bad manifest: %w", err)
	}
	return m, nil
}

// ID computes the stable repligraph identity: BLAKE3 of the manifest bytes.
func ID(fsys fs.FS) (string, error) {
	blob, err := fs.ReadFile(fsys, ManifestName)
	if err != nil {
		return "", err
	}
	sum := blake3.Sum256(blob)
	return hex.EncodeToString(sum[:]), nil
}

func ResolveProfile(name string) (tools.Limits, token.Codec, error) {
	if name != "default" {
		return tools.Limits{}, nil, fmt.Errorf("unknown profile %q", name)
	}
	return tools.DefaultLimits, token.Bytes, nil
}

type Writer struct {
	dir     string
	profile string
	f       *os.File
	rec     *Recorder
	closed  bool
}

func NewWriter(dir string, profile string, prefill []uint32) (*Writer, error) {
	lim, codec, err := ResolveProfile(profile)
	if err != nil {
		return nil, err
	}
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return nil, err
	}
	f, err := os.OpenFile(filepath.Join(dir, TranscriptName), os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o644)
	if err != nil {
		return nil, fmt.Errorf("bundle already has a transcript: %w", err)
	}
	rec, err := NewRecorder(f, lim, codec, prefill)
	if err != nil {
		f.Close()
		return nil, err
	}
	return &Writer{dir: dir, profile: profile, f: f, rec: rec}, nil
}

func (w *Writer) Turn(gen []token.Token) ([]uint32, bool, error) {
	return w.rec.Turn(gen)
}

func (w *Writer) Tree() tree.Tree { return w.rec.Tree() }

func (w *Writer) Close() error {
	if w.closed {
		return fmt.Errorf("bundle writer is closed")
	}
	if !w.rec.Finished() {
		return fmt.Errorf("session did not finish; refusing to seal the bundle")
	}
	w.closed = true
	if err := w.f.Close(); err != nil {
		return err
	}
	tblob, err := os.ReadFile(filepath.Join(w.dir, TranscriptName))
	if err != nil {
		return err
	}
	tsum := blake3.Sum256(tblob)

	adir := filepath.Join(w.dir, ArtifactDir)
	err = w.rec.Tree().WalkFiles("/", func(p string, f tree.File) error {
		dst := filepath.Join(adir, filepath.FromSlash(p))
		if err := os.MkdirAll(filepath.Dir(dst), 0o755); err != nil {
			return err
		}
		mode := os.FileMode(0o644)
		if f.Exec {
			mode = 0o755
		}
		return os.WriteFile(dst, f.Content, mode)
	})
	if err != nil {
		return err
	}

	m := Manifest{
		Version:        1,
		Profile:        w.profile,
		TranscriptHash: tsum,
		ArtifactRoot:   w.rec.Tree().Root(),
	}
	blob, err := json.MarshalIndent(m, "", "  ")
	if err != nil {
		return err
	}
	return os.WriteFile(filepath.Join(w.dir, ManifestName), append(blob, '\n'), 0o644)
}

func Verify(fsys fs.FS) (*Report, error) {
	m, err := ReadManifest(fsys)
	if err != nil {
		return nil, err
	}
	if m.Version != 1 {
		return nil, fmt.Errorf("unsupported bundle version %d", m.Version)
	}
	lim, codec, err := ResolveProfile(m.Profile)
	if err != nil {
		return nil, err
	}
	id, err := ID(fsys)
	if err != nil {
		return nil, err
	}

	fail := func(rep *Report, format string, args ...any) (*Report, error) {
		rep.Failure = &Failure{Segment: -1, Pos: -1, Reason: fmt.Sprintf(format, args...)}
		return rep, nil
	}

	const maxTranscriptSize = 1024 * (1 << 20) // 1 GiB
	if stat, err := fs.Stat(fsys, TranscriptName); err != nil {
		return nil, err
	} else if stat.Size() > maxTranscriptSize {
		return nil, fmt.Errorf("transcript is too large: %d bytes", stat.Size())
	}
	tblob, err := fs.ReadFile(fsys, TranscriptName)
	if err != nil {
		return nil, err
	}
	if tsum := blake3.Sum256(tblob); tsum != m.TranscriptHash {
		return fail(&Report{ID: id, Tree: tree.Empty()},
			"transcript hash mismatch: manifest says %s, file hashes to %s", m.TranscriptHash, tsum)
	}

	rep, err := Replay(bytes.NewReader(tblob), lim, codec)
	if err != nil {
		return nil, err
	}
	rep.ID = id
	if !rep.OK() {
		return rep, nil
	}

	if rep.FinalRoot != m.ArtifactRoot {
		return fail(rep, "artifact root claim mismatch: manifest says %s, replay derives %s", m.ArtifactRoot, rep.FinalRoot)
	}
	afs, err := fs.Sub(fsys, ArtifactDir)
	if err != nil {
		return nil, fmt.Errorf("artifact: %w", err)
	}
	at, err := tree.FromFS(afs)
	if err != nil {
		return nil, fmt.Errorf("artifact: %w", err)
	}
	if got := at.Root(); got != rep.FinalRoot {
		return fail(rep, "artifact directory does not match the transcript: treehash %s, replay derives %s", got, rep.FinalRoot)
	}
	return rep, nil
}

// Package token is the harness's bundled tokenization layer. The transcript
// deals in token ids, never text: tool results are encoded by the harness
// before the model sees them, and generated segments are decoded by the
// harness to extract tool calls. The codec is therefore part of the pinned
// environment — its name is recorded in the transcript header and a verifier
// resolves it against its own registry, exactly like model pins.
package token

import "fmt"

// Token is one generated token: the id is the ground truth the model check
// regenerates and compares; the logprob is a recorded claim, informational
// to the environment side.
type Token struct {
	ID      uint32
	Logprob float32
}

// Codec converts between text and token ids. Encode must be a pure function
// of its input; Decode must reject ids outside the vocabulary rather than
// guessing.
type Codec interface {
	Name() string
	Encode(text string) []uint32
	Decode(ids []uint32) (string, error)
}

// ByName resolves a codec from this harness's registry. Unknown names are an
// error: a verifier must never improvise a tokenizer.
func ByName(name string) (Codec, error) {
	if name == Bytes.Name() {
		return Bytes, nil
	}
	return nil, fmt.Errorf("unknown codec %q", name)
}

// Bytes is the v1 codec: token id = byte value. It is trivially reversible,
// so encode∘decode is the identity and the token/text seam that plagues real
// BPE vocabularies (encode is non-injective over text) cannot appear. Real
// model tokenizers implement Codec behind their own pinned names.
var Bytes Codec = byteCodec{}

type byteCodec struct{}

func (byteCodec) Name() string { return "bytes/v1" }

func (byteCodec) Encode(text string) []uint32 {
	ids := make([]uint32, len(text))
	for i := 0; i < len(text); i++ {
		ids[i] = uint32(text[i])
	}
	return ids
}

func (byteCodec) Decode(ids []uint32) (string, error) {
	b := make([]byte, len(ids))
	for i, id := range ids {
		if id > 0xff {
			return "", fmt.Errorf("token id %d is outside the bytes/v1 vocabulary", id)
		}
		b[i] = byte(id)
	}
	return string(b), nil
}
